+      place-items: center;
+      padding: 32px 16px;
+    }
+
+    .page {
+      width: min(860px, 100%);
+      background: var(--panel);
+      border: 1px solid var(--border);
+      border-radius: 24px;
+      box-shadow: var(--shadow);
+      padding: 32px;
+      backdrop-filter: blur(18px);
+    }
+
+    .eyebrow {
+      margin: 0 0 8px;
+      color: var(--accent);
+      font-size: 0.85rem;
+      font-weight: 700;
+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 4vw, 3rem);
+      line-height: 1.1;
+    }
+
+    .intro {
+      margin: 14px 0 30px;
+      max-width: 60ch;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.7;
+    }
+
+    .faq {
+      display: grid;
+      gap: 14px;
+    }
+
+    .example {
+      background: linear-gradient(180deg, rgba(30, 41, 59, 0.7), rgba(15, 23, 42, 0.88));
+      border: 1px solid var(--border);
+      border-radius: 18px;
+      overflow: hidden;
+      transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
+    }
+
+    .example:hover {
+      transform: translateY(-1px);
+      border-color: rgba(125, 211, 252, 0.36);
+      box-shadow: 0 18px 40px rgba(15, 23, 42, 0.35);
+    }
+
+    .question {
+      width: 100%;
+      border: 0;
+      background: transparent;
+      color: inherit;
+      cursor: pointer;
+      padding: 20px 22px;
+      font-size: 1.05rem;
+      font-weight: 700;
+      text-align: left;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+    }
+
+    .question:focus-visible {
+      outline: 2px solid var(--accent-strong);
+      outline-offset: -2px;
+    }
+
+    .question::after {
+      content: "+";
+      flex: 0 0 auto;
+      width: 32px;
+      height: 32px;
+      border-radius: 50%;
+      background: rgba(125, 211, 252, 0.12);
+      color: var(--accent);
+      display: grid;
+      place-items: center;
+      font-size: 1.35rem;
+      transition: transform 0.2s ease, background-color 0.2s ease;
+    }
+
+    .question[aria-expanded="true"]::after {
+      content: "–";
+      background: rgba(56, 189, 248, 0.2);
+      transform: rotate(180deg);
+    }
+
+    .details {
+      padding: 0 22px 22px;
+      color: #cbd5e1;
+      line-height: 1.7;
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    @media (max-width: 600px) {
+      .page {
+        padding: 24px 18px;
+        border-radius: 20px;
+      }
+
+      .question {
+        padding: 18px;
+      }
+
+      .details {
+        padding: 0 18px 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <p class="eyebrow">Cat care guide</p>
+    <h1>Frequently Asked Questions About Cats</h1>
+    <p class="intro">
+      Explore quick answers about feline behavior, nutrition, and daily care. Each question starts collapsed and opens with a click.
+    </p>
+
+    <section class="faq" aria-label="Cat FAQ">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-1">
+          Why do cats purr?
+        </button>
+        <div class="details" id="faq-1" hidden>
+          <p>Cats often purr when they feel relaxed, safe, and content, but they may also purr to soothe themselves when stressed or recovering. It is a versatile sound linked to comfort, communication, and self-regulation.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-2">
+          How often should I feed my cat?
+        </button>
+        <div class="details" id="faq-2" hidden>
+          <p>Most adult cats do well with two measured meals per day, while kittens usually need more frequent feeding. The ideal amount depends on age, activity level, and the food itself, so portion guidance on the label and veterinary advice are both helpful.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-3">
+          Why do cats knead with their paws?
+        </button>
+        <div class="details" id="faq-3" hidden>
+          <p>Kneading is a behavior many cats carry from kittenhood, when they pressed against their mother to encourage milk flow. Adult cats often knead soft surfaces when they feel calm, cozy, and secure.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-4">
+          Do indoor cats need enrichment?
+        </button>
+        <div class="details" id="faq-4" hidden>
+          <p>Yes. Indoor cats benefit from climbing spaces, scratching posts, interactive toys, puzzle feeders, and regular play sessions. Enrichment helps reduce boredom and supports healthy exercise and natural hunting instincts.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-5">
+          How can I tell if my cat is stressed?
+        </button>
+        <div class="details" id="faq-5" hidden>
+          <p>Common signs include hiding more than usual, reduced appetite, over-grooming, vocal changes, or avoiding the litter box. Sudden behavior changes should be taken seriously because stress and illness can look similar.</p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    const questions = document.querySelectorAll(".question");
+
+    questions.forEach((button) => {
+      button.addEventListener("click", () => {
+        const details = document.getElementById(button.getAttribute("aria-controls"));
+        const isExpanded = button.getAttribute("aria-expanded") === "true";
+
+        button.setAttribute("aria-expanded", String(!isExpanded));
+        details.hidden = isExpanded;
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
